def make_question(index,row):
 tag,prompt,options,answer,reason=row
 # 讓答案位置分布為 A2/B3/C3/D2；先保留原選項文字，再只調整位置，避免答案字母偏差。
 target_letters=["A","B","C","D","B","C","D","A","C","B"]
 target=target_letters[index-1]
 distractors=[t for t in options if t != answer]
 ordered=[]; di=0
 for letter in ["A","B","C","D"]:
  if letter == target: ordered.append(answer)
  else: ordered.append(distractors[di]); di += 1
 opts=[{"id":chr(65+i),"text":t} for i,t in enumerate(ordered)]; aid=target
 refs=[{"url":u,"title":f"{t}；僅研究公開題型與能力方向，未複製原題。","year":"113-114","subject":"social","locator":l,"observedPattern":"公立學校社會科公開試題常見的改革、經濟、人口、全球化與多重資料推理能力，經本題重新設計。","reuseDecision":"pattern-only","status":"recorded","locatorLevel":"paper"} for u,t,l in SOURCES]
 steps=[f"讀題定位：圈出「{tag}」並標記改革政策、經濟指標、群體或資料類型。",f"整理證據：分開政策目標、制度安排、成長數字、分配與生活代價；本題核心是「{reason}」。",f"核對正解：選項 {aid}「{answer}」能同時回應題幹資料與改革開放與政經變遷的歷史推理。","排除誘答：檢查是否把 GDP、出口或建設等同所有人受益，或把改革簡化成國家與市場二選一。","結論回查：確認時間、區域、階層、移動者與資料限制都已納入。"]
 return {"id":f"question-social-content-hist-la-iv-2-{index}","subject":"social","type":"single-choice","prompt":prompt,"options":opts,"knowledgeIds":["kg-social-content-hist-la-iv-2"],"difficulty":"medium","answer":{"value":aid,"explanation":reason},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0][0],"sourceLocator":"高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。","authoringNote":"依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫農村改革、經濟特區、市場國家、人口流動、國企改革、全球產業、教育階層、城市環境、兩岸交流與改革評估情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":"lesson-social-content-hist-la-iv-2","examPatternRefs":refs,"solutionStrategy":"先區分改革政策與市場結果，再比較農村、城市、企業、人口、教育、環境及兩岸資料，最後用總量與分配指標共同評估改革成效。","solutionSteps":steps}

